using System.Diagnostics; using Dip.Shared.Contracts.Api; namespace Dip.Api.Middleware; public sealed class ExceptionHandlingMiddleware{private readonly RequestDelegate _next;private readonly ILogger<ExceptionHandlingMiddleware> _log;public ExceptionHandlingMiddleware(RequestDelegate n,ILogger<ExceptionHandlingMiddleware> l){_next=n;_log=l;}public async Task InvokeAsync(HttpContext c){try{await _next(c);}catch(KeyNotFoundException ex){await Write(c,404,"not_found",ex.Message);}catch(ArgumentException ex){await Write(c,400,"validation_error",ex.Message);}catch(Exception ex){_log.LogError(ex,"Unhandled exception");await Write(c,500,"internal_error","Unexpected error.");}}private static async Task Write(HttpContext c,int status,string type,string title){c.Response.StatusCode=status;c.Response.ContentType="application/json";var trace=Activity.Current?.TraceId.ToString()??c.TraceIdentifier;await c.Response.WriteAsJsonAsync(new ApiError(type,title,status,trace));}}